/// (sıra, başlık, kural, örnek, gövde) — tecvid dersleri (Hafs rivayeti).
/// Örnek Arapça, Kur'an metninden birebir alınmıştır; gövdede sure ve âyet belirtilir.
const List<(int, String, String, String, String)> kTajweedSeed = [
  (1, 'Harflerin Mahreçleri', 'Her Arap harfi, ağız ve boğazdaki belirli bir çıkış yerinden (mahreç) çıkar.', 'ٱلْحَمْدُ لِلَّهِ',
      'Mahreç, harfin çıktığı yerdir. Harfler beş ana bölgeden çıkar: cevf (ağız ve boğaz boşluğu; med harfleri), halk (boğaz), lisan (dil), şefeteyn (dudaklar) ve hayşûm (burun boşluğu; gunne). Boğaz harfleri altıdır: ء ه ع ح غ خ. Dil harfleri on sekizdir. Dudak harfleri ب م و ile ف harfidir; ف, alt dudağın iç kısmı ile üst ön dişlerin ucundan çıkar. Örnekteki ٱلْحَمْدُ لِلَّهِ ifadesinde ح boğazdan, ل ve د dilden, م dudaklardan çıkar. Mahreci doğru bilmek, harfleri birbirine karıştırmadan okumanın temelidir. Örnek, Fâtiha, 2. âyetten alınmıştır.'),
  (2, 'Şedde', 'Şeddeli harf, biri sâkin biri harekeli iki harf gibi okunur ve pekiştirilir.', 'إِيَّاكَ نَعْبُدُ',
      'Şedde (ـّ), bir harfin tekrarlandığını gösteren işarettir. Şeddeli harf, ilki sâkin ikincisi harekeli iki harf gibi okunur; bu yüzden harfin üzerinde bir miktar durulur ve ses pekiştirilir. Örnekteki إِيَّاكَ kelimesinde ي harfi şeddelidir: önce sâkin bir ي, hemen ardından harekeli bir ي okunur. Şeddeyi hafif geçmek kelimeyi ve bazen anlamı bozar. Şeddeli nûn ve mîm harflerinde ayrıca gunne yapılır; bu konu ayrı bir derstedir. Örnek, Fâtiha, 5. âyetten alınmıştır.'),
  (3, 'Med-i Tabiî', 'Med harfi, kendinden sonra sebep gelmediğinde iki hareke miktarı uzatılır.', 'قَالَ رَبُّكَ',
      'Med harfleri üçtür: elif, vâv ve yâ. Elif’ten önceki harf fethalı, sâkin vâv’dan önceki harf ötreli, sâkin yâ’dan önceki harf esreli olduğunda bu harfler med harfi olur. Kendinden sonra hemze veya sükûn gibi bir sebep gelmediğinde yapılan uzatmaya med-i tabiî denir ve iki hareke (bir elif) miktarı sürer. Örnekteki قَالَ kelimesinde ق fethalıdır ve ardından gelen elif iki hareke uzatılır. Uzatma ne eksik ne fazla olmalıdır. Örnek, Bakara, 30. âyetten alınmıştır.'),
  (4, 'Lâm-ı Şemsiyye ve Kameriyye', '“El” takısındaki lâm, güneş harflerinden önce okunmaz; ay harflerinden önce okunur.', 'ٱلنَّاسِ — ٱلْحَمْدُ',
      'Kelimenin başındaki ٱلْ takısının lâm’ı, kendinden sonra gelen harfe göre değişir. Şemsiyye (güneş) harfleri on dörttür: ت ث د ذ ر ز س ش ص ض ط ظ ل ن. Bu harflerden önce lâm okunmaz, sonraki harf şeddeli okunur. Kameriyye (ay) harfleri de on dörttür: ء ب غ ح ج ك و خ ف ع ق ي م ه. Bunlardan önce lâm açıkça okunur. Örneklerde ٱلنَّاسِ kelimesinde lâm okunmaz (ن şeddelenir), ٱلْحَمْدُ kelimesinde lâm okunur. Örnekler, Bakara, 8 ve Fâtiha, 2. âyetlerden alınmıştır.'),
  (5, 'Kalkale', 'Kalkale harfleri (ق ط ب ج د) sâkin olunca yankılı bir titreşimle okunur.', 'يَطْلُبُهُۥ — يَجْعَلُونَ — أَحَدٌ',
      'Kalkale, sâkin olan kalkale harfinin ses yankısıyla okunmasıdır. Harfleri ق ط ب ج د şeklinde beştir ve “kutbü ced” diye hatırlanır. Harf kelimenin ortasında sâkin olduğunda yankı hafiftir; vakıf yapılan yerde yankı daha belirgindir. Örneklerde يَطْلُبُهُۥ kelimesinde ط, يَجْعَلُونَ kelimesinde ج sâkindir. أَحَدٌ kelimesinde durulduğunda د harfi sâkin olur ve kalkale ile okunur. Kalkaleyi harekeye çevirmemeye dikkat edilir. Örnekler, A’râf, 54; Bakara, 19 ve İhlâs, 1. âyetlerden alınmıştır.'),
  (6, 'Gunne', 'Şeddeli nûn ve mîm, iki hareke miktarı gunne ile okunur.', 'إِنَّ — ثُمَّ',
      'Gunne, sesin burun boşluğundan getirilmesidir. Şeddeli nûn (نّ) ve şeddeli mîm (مّ) her durumda yaklaşık iki hareke gunne ile okunur; buna gunne-i müşeddede denir. Örneklerde إِنَّ kelimesindeki nûn ve ثُمَّ kelimesindeki mîm şeddelidir. Durakta (vakıf) da bu gunne korunur. Gunneyi kesmek ya da fazla uzatmak okuyuşu bozar. Nûn ve mîm harfleri sâkin olduklarında ise yerine göre izhâr, ihfâ, idğâm veya iklâb hükümlerine tâbi olur; şeddeli olduklarında bu hükümlerden bağımsız olarak gunne yapılır. Örnekler, A’râf, 54. âyetten alınmıştır.'),
  (7, 'İzhâr', 'Sâkin nûn veya tenvinden sonra boğaz harfleri gelirse nûn açıkça okunur.', 'عَذَابٌ عَظِيمٌۭ — أَنْعَمْتَ',
      'İzhâr, açığa çıkarma demektir. Sâkin nûn veya tenvinden sonra altı boğaz harfinden biri gelirse nûn sesi gizlenmeden, gunne yapılmadan net okunur. Bu harfler: ء ه ع ح غ خ. Örneklerde عَذَابٌ عَظِيمٌۭ ifadesinde tenvinden sonra ع gelir; أَنْعَمْتَ kelimesinde sâkin nûn’dan sonra yine ع gelir. İkisinde de nûn sesi belirgin okunur. Çünkü bu harflerin mahreci nûn’dan uzaktır ve nûn’un onlara kaynaşmasına imkân vermez. Örnekler, Bakara, 7 ve Fâtiha, 7. âyetlerden alınmıştır.'),
  (8, 'İdğâm bi-Gunne', 'Sâkin nûn veya tenvinden sonra ي ن م و gelirse kaynaşır ve gunne yapılır.', 'مَن يَقُولُ',
      'İdğâm, bir harfin kendinden sonrakine katılmasıdır. Sâkin nûn veya tenvinden sonra ي ن م و harfleri (“yenmû”) ayrı bir kelimede gelirse nûn sesi o harfe katılır ve iki hareke kadar gunne ile okunur. Örnekteki مَن يَقُولُ ifadesinde nûn, ي harfine katılır. Nûn ile idğâm harfi aynı kelimede ise idğâm yapılmaz, izhâr yapılır; bunlar dünyâ, kınvân, sınvân ve bunyân kelimeleridir. Gunnenin eksik veya fazla yapılması okuyuşu bozar. Örnek, Bakara, 8. âyetten alınmıştır.'),
  (9, 'İdğâm bilâ Gunne', 'Sâkin nûn veya tenvinden sonra ل veya ر gelirse gunnesiz kaynaşır.', 'مِن رَّبِّكَ',
      'Sâkin nûn veya tenvinden sonra ل ya da ر harfi gelirse nûn sesi tamamen o harfe katılır ve gunne yapılmaz. İdğâm harfleri altıdır: ي ر م ل و ن, yani “yermelûn”. Bunlardan ل ve ر gunnesiz, diğer dördü gunneli idğâm yapar. Örnekteki مِن رَّبِّكَ ifadesinde nûn, ر harfine katılır ve ر şeddeli okunur; arada gunne duyulmaz. İdğâm, iki kelimenin birleştiği yerde yapılır. Örnek, Bakara, 147. âyetten alınmıştır.'),
  (10, 'İklâb', 'Sâkin nûn veya tenvinden sonra ب gelirse nûn, gunneli bir mîm sesine çevrilir.', 'مِنۢ بَعْدِ — سَمِيعًۢا بَصِيرًۭا',
      'İklâb, çevirme demektir. Sâkin nûn veya tenvinden sonra yalnız ب harfi gelirse nûn sesi mîm sesine çevrilir; dudaklar hafifçe birleştirilir ve iki hareke miktarı gunne yapılır. Mushafta iklâb durumlarında tenvin/nûn üzerinde küçük bir mîm işareti görülür; ancak bu işaret tek başına iklâbı belirlemez, kuralı belirleyen ardındaki harfin be (ب) olmasıdır. Örneklerde مِنۢ بَعْدِ ifadesinde nûn, سَمِيعًۢا بَصِيرًۭا ifadesinde tenvin mîm sesine döner. ب harfi ayrıca okunur; yalnızca nûn sesi dönüşür. Örnekler, Bakara, 27 ve Nisâ, 58. âyetlerden alınmıştır.'),
  (11, 'İhfâ', 'Sâkin nûn veya tenvinden sonra 15 ihfâ harfinden biri gelirse nûn gizlenir.', 'أَندَادًۭا — مِن قَبْلِكَ',
      'İhfâ, gizleme demektir; izhâr ile idğâm arasında bir okuyuştur. Sâkin nûn veya tenvinden sonra on beş harften biri gelirse nûn net okunmaz, gunneyle gizlenir. Bu harfler: ت ث ج د ذ ز س ش ص ض ط ظ ف ق ك. Dil, nûn’un mahrecine yaklaşır fakat tam değmez; ses burundan iki hareke kadar gelir. Örneklerde أَندَادًۭا kelimesinde nûn’dan sonra د, مِن قَبْلِكَ ifadesinde nûn’dan sonra ق gelir. Örnekler, Bakara, 22 ve Bakara, 4. âyetlerden alınmıştır.'),
  (12, 'İhfâ-yı Şefevî', 'Sâkin mîmden sonra ب gelirse mîm gizlenir ve gunne yapılır.', 'تَرْمِيهِم بِحِجَارَةٍۢ',
      'Sâkin mîm, üzerinde sükûn bulunan mîm harfidir. Sâkin mîmden sonra ب harfi gelirse mîm net okunmaz; dudaklar sıkılmadan hafifçe birleştirilir ve iki hareke miktarı gunne yapılır. Buna ihfâ-yı şefevî (dudak ihfâsı) denir. Örnekteki تَرْمِيهِم بِحِجَارَةٍۢ ifadesinde mîm, ب harfinden önce gizlenir. Mîm’in ve ب’nin mahreci dudaklardır. Mîm’i tam kapatıp açıkça okumak yanlıştır. Sâkin mîm hükümleri üçtür: ihfâ-yı şefevî, idğâm-ı misleyn ve izhâr-ı şefevî; sonraki iki hüküm ayrı bir derstedir. Örnek, Fîl, 4. âyetten alınmıştır.'),
  (13, 'İdğâm-ı Misleyn ve İzhâr-ı Şefevî', 'Sâkin mîmden sonra mîm gelirse gunneli idğâm; ب ve م dışındaki harfler gelirse izhâr yapılır.', 'وَلَهُم مَّا — وَهُمْ فِيهَا',
      'Sâkin mîmden sonra mîm harfi gelirse iki mîm kaynaşır ve şeddeli mîm gibi iki hareke gunne ile okunur; buna idğâm-ı misleyn (şefevî) denir. Örnekteki وَلَهُم مَّا ifadesinde böyledir. Sâkin mîmden sonra ب ve م dışındaki harflerden biri gelirse mîm açıkça okunur; buna izhâr-ı şefevî denir. Örnekteki وَهُمْ فِيهَا ifadesinde mîm net okunur. Özellikle و ve ف harflerinden önce mîm’in gizlenmemesine dikkat edilir. Örnekler, Yâsîn, 57 ve Bakara, 25. âyetlerden alınmıştır.'),
  (14, 'Med-i Muttasıl', 'Med harfinden sonra aynı kelimede hemze gelirse med dört-beş hareke uzatılır.', 'مِنَ ٱلسَّمَآءِ',
      'Med harfinden sonra, aynı kelime içinde hemze geliyorsa uzatma sebebi vardır; buna med-i muttasıl (bitişik med) denir. Hafs rivayetinde bu med dört-beş hareke miktarı uzatılır ve vâcib kabul edilir. Örnekteki مِنَ ٱلسَّمَآءِ ifadesinde ٱلسَّمَآءِ kelimesinde elif’ten sonra hemze gelmiştir; elif bu nedenle uzatılır. Tabiî medden farkı, hemze gibi bir sebebin aynı kelimede bulunmasıdır. Okuyucu aynı okumada ölçüyü korur. Örnek, Bakara, 22. âyetten alınmıştır.'),
  (15, 'Med-i Munfasıl', 'Med harfi bir kelimenin sonunda, hemze sonraki kelimenin başındaysa med dört-beş hareke uzatılır.', 'بِمَآ أُنزِلَ',
      'Med harfi bir kelimenin sonunda, hemze ise hemen sonraki kelimenin başında bulunduğunda uzatma sebebi oluşur; buna med-i munfasıl (ayrık med) denir. Hafs rivayetinde bu med de dört-beş hareke uzatılır ve câiz kabul edilir. Örnekteki بِمَآ أُنزِلَ ifadesinde بِمَآ kelimesinin sonundaki elif, sonraki kelimenin başındaki hemzeden dolayı uzatılır. Muttasıldan farkı, sebebin ayrı bir kelimede olmasıdır. Okuyucu aynı okumada hangi ölçüyü seçtiyse onu korur. Örnek, Bakara, 4. âyetten alınmıştır.'),
  (16, 'Med-i Lâzım', 'Med harfinden sonra aynı kelimede aslî sükûn veya şedde gelirse med altı hareke uzatılır.', 'ٱلضَّآلِّينَ',
      'Med harfinden sonra kalıcı bir sükûn veya şedde geliyorsa med altı hareke uzatılır; buna med-i lâzım denir. Sükûnun kalıcı olması, vakıf yapılsın ya da yapılmasın değişmemesi demektir. Şeddeli kelimelerdeki bu duruma kelime-i müsekkel denir. Örnekteki ٱلضَّآلِّينَ kelimesinde elif’ten sonra şeddeli ل gelir ve elif altı hareke uzatılır. Lâzım med, tabiî ve diğer med türlerinden daha uzun okunur; kısaltılırsa okuyuş bozulur. Okuyucu, uzatma süresini âyet boyunca eşit tutmaya dikkat eder. Örnek, Fâtiha, 7. âyetten alınmıştır.'),
  (17, 'Vakıf (Durak)', 'Vakıf, nefes alıp okuyuşa ara vermektir; son harf sâkin okunur.', 'قُلْ هُوَ ٱللَّهُ أَحَدٌ',
      'Vakıf, kelimenin sonunda soluk alacak kadar durmaktır. Vakıf yapılan harf sâkin okunur; son harekeler düşer. Fetha tenvini (ـً) vakıfta elife dönüşür, tâ-i merbûta (ة) ise hâ (ه) gibi okunur. Âyet sonları durmak için en uygun yerlerdir. Örnekteki أَحَدٌ kelimesinde vakıf yapılırsa tenvin düşer ve د sâkin okunur; kalkale de yapılır. Anlamı bozan yerde durmaktan kaçınılır; gerekirse bir önceki uygun yerden yeniden başlanır. Örnek, İhlâs, 1. âyetten alınmıştır.'),
  (18, 'Med-i Âriz ve Lîn', 'Vakıf sebebiyle sâkin olan harften önceki med (âriz) ve lîn harfi, vakıfta uzatılabilir.', 'ٱلْعَٰلَمِينَ — نَسْتَعِينُ — وَءَامَنَهُم مِّنْ خَوْفٍۭ',
      'Vakıf yapıldığında son harf sâkin olur. Bu sükûn geçici olduğundan, ondan önceki med harfinin uzatılmasına med-i âriz denir; iki, dört veya altı hareke okunabilir. Örneklerde ٱلْعَٰلَمِينَ ve نَسْتَعِينُ kelimeleri durulunca uzatılır. Lîn harfleri ise kendinden önceki harf fethalı olan sâkin vâv ve yâ’dır. Bunların ardından vakıfla sâkin olan harf gelirse lîn uzatılabilir. Örnekteki وَءَامَنَهُم مِّنْ خَوْفٍۭ ifadesinde vakıf yapılırsa وْ yumuşak bir uzatmayla okunur. Vasıl yapıldığında bu uzatmalar yapılmaz. Örnekler, Fâtiha, 2; Fâtiha, 5 ve Kureyş, 4. âyetlerden alınmıştır.'),
  (19, 'Sıla (Hâ-i Damir)', 'İki harekeli harf arasındaki “o” zamiri, sonrasında hemze yoksa iki hareke uzatılır.', 'يُضِلُّ بِهِۦ كَثِيرًۭا — يُضِلُّ بِهِۦٓ إِلَّا',
      'Hâ-i damir, “onun, ona” anlamındaki zamir harfidir. Önünde ve ardında harekeli bir harf varsa hâ’nın sonunda kısa bir med harfi okunur; buna sıla denir. Sonrasında hemze yoksa sıla-i suğrâ olur ve iki hareke uzatılır. Örnekteki يُضِلُّ بِهِۦ كَثِيرًۭا ifadesi böyledir. Sonrasında hemze varsa sıla-i kübrâ olur ve munfasıl med gibi uzatılır. Örnekteki يُضِلُّ بِهِۦٓ إِلَّا ifadesinde hâ’dan sonra hemze gelir. Önünde ya da ardında sâkin harf varsa sıla yapılmaz (Furkân, 69 bir istisnadır: önünde sâkin yâ olduğu hâlde sıla yapılır). Örnekler, Bakara, 26. âyetten alınmıştır.'),
  (20, 'Râ Harfi: Tefhîm ve Terkîk', 'Râ harfi fetha veya dammede kalın, kesrede ince okunur.', 'رَبِّ — رِزْقًۭا',
      'Râ harfinin kalın okunmasına tefhîm, ince okunmasına terkîk denir. Harekeli râ, fethalı ya da ötreliyse kalın, esreliyse ince okunur. Örnekte رَبِّ kelimesinde râ fethalıdır ve kalın okunur; رِزْقًۭا kelimesinde râ esrelidir ve ince okunur. Sâkin râ’da, kendinden önceki harekeye bakılır: önce fetha veya damme varsa kalın, kesre varsa ince okunur. Bu temel hüküm dışında özel durumlar vardır; ayrıntıları bir hocadan öğrenmek gerekir. Örnekler, Fâtiha, 2 ve Bakara, 22. âyetlerden alınmıştır.'),
  (21, 'Lafza-i Celâl', '“Allah” lafzındaki lâm, öncesinde fetha veya damme varsa kalın, kesre varsa ince okunur.', 'رَبَّكُمُ ٱللَّهُ — بِسْمِ ٱللَّهِ',
      'Lafza-i Celâl, “Allah” lafzının (ٱللَّهُ) adıdır. Bu lafzın lâm’ı kendinden önceki harekeye göre okunur. Önündeki harf fethalı veya ötreliyse lâm kalın okunur (tefhîm). Önündeki harf esreliyse lâm ince okunur (terkîk). Örnekteki رَبَّكُمُ ٱللَّهُ ifadesinde damme olduğu için lâm kalın okunur; بِسْمِ ٱللَّهِ ifadesinde ise esre olduğu için lâm ince okunur. Lafzın cümle başında geldiği yerde de lâm kalın okunur. Örnekler, A’râf, 54 ve Fâtiha, 1 (Besmele) âyetlerinden alınmıştır.'),
  (22, 'Hemze: Kat’ ve Vasl', 'Kat’ hemzesi her zaman okunur; vasl hemzesi yalnız başta okunur, ortada düşer.', 'أَنزَلَ — ٱللَّهِ ٱلرَّحْمَٰنِ',
      'Hemze iki türlüdür. Kat’ hemzesi (ء ، أ ، إ), kelimenin başında olduğu gibi okuyuşun ortasında da kesinlikle okunur. Örnekteki أَنزَلَ kelimesinde hemze her zaman okunur. Vasl hemzesi ise kelimenin başındaki ٱ ile gösterilir; okuyuşa onunla başlanırsa okunur, öncesinde bir kelime varsa okunmaz ve iki kelime birbirine bağlanır. Örnekteki ٱللَّهِ ٱلرَّحْمَٰنِ ifadesinde ٱلرَّحْمَٰنِ kelimesinin başındaki hemze, önceki kelimeyle birleşince okunmaz. Örnekler, Kehf, 1 ve Fâtiha, 1 (Besmele) âyetlerinden alınmıştır.'),
  (23, 'Durak İşaretleri ve İbtidâ', 'Mushaftaki küçük işaretler durmanın hükmünü gösterir; durulan yerden anlama uygun başlanır.', 'لَا رَيْبَ ۛ فِيهِ ۛ — رِّزْقًۭا ۙ',
      'Medine Mushafı’nda kullanılan işaretler şunlardır: ۘ (vakf-ı lâzım) durulmalıdır, ۗ durmak evlâdır, ۚ durmak câizdir, ۖ geçmek evlâdır, ۙ (lâ) durulmaz, ۛ ise (muânaka) iki işaretten yalnız birinde durulur. Örnekte لَا رَيْبَ ۛ فِيهِ ۛ ifadesinde iki yerden yalnız birinde durulabilir. رِّزْقًۭا ۙ ifadesinde ise durulmaz. İbtidâ, durduktan sonra yeniden başlamaktır; başlanılan yer anlamı bozmamalı ve önceki cümleyle yanlış bağ kurulmamalıdır. Örnekler, Bakara, 2 ve Bakara, 25. âyetlerden alınmıştır.'),
  (24, 'Sekte', 'Sekte, nefes almadan, kısa bir süre durup devam etmektir.', 'يَجْعَل لَّهُۥ عِوَجَا ۜ',
      'Sekte, nefes almadan kelimeyi kısa bir süre kesip okumaya devam etmektir. Hafs rivayetinde dört yerde yapılır: Kehf Suresi’nde 1. âyetteki عِوَجَا kelimesinden sonra, Yâsîn Suresi’nde 52. âyette مَرْقَدِنَا kelimesinden sonra, Kıyâme Suresi’nde 27. âyette مَنْ kelimesinden sonra, Mutaffifîn Suresi’nde 14. âyette بَلْ kelimesinden sonra. Mushafta bu yerlerde küçük bir س işareti bulunur. Örnekteki يَجْعَل لَّهُۥ عِوَجَا ۜ ifadesinde Kehf’teki sekte görülür. Örnek, Kehf, 1. âyetten alınmıştır.'),
];
